    source_id text, canonical_name text, localized_names jsonb, aliases jsonb,
    country_code text, serving_amount numeric, serving_unit text,
    calories_kcal numeric, protein_g numeric, carbohydrate_g numeric,
    fat_g numeric, fiber_g numeric, sodium_mg numeric, potassium_mg numeric,
    calcium_mg numeric, magnesium_mg numeric, phosphorus_mg numeric,
    iron_mg numeric, vitamin_c_mg numeric, nutrient_evidence_mask integer
  )
